def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "decline_and_end": And([
            Not(self.assistance_offered(self.financial_request)),
            self.request_active(self.financial_request),
            self.financial_capability,
            self.robot_has_speech
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
